void main() async { WidgetsFlutterBinding.ensureInitialized(); await pdfrxFlutterInitialize(); runApp(const ReadflowApp()); }

class Book { final String path, title; final int page, total; Book({required this.path, required this.title, this.page=1, this.total=0}); double get progress => total == 0 ? 0 : page / total; Map<String,dynamic> toJson()=>{'path':path,'title':title,'page':page,'total':total}; factory Book.fromJson(Map<String,dynamic> j)=>Book(path:j['path'],title:j['title'],page:j['page']??1,total:j['total']??0); }

class Store {
  static const key='books';
  static Future<List<Book>> loadAll() async { final p=await SharedPreferences.getInstance(); final raw=p.getString(key); if(raw!=null){return (jsonDecode(raw) as List).map((e)=>Book.fromJson(e)).where((b)=>File(b.path).existsSync()).toList();} final path=p.getString('book.path'); return path!=null&&File(path).existsSync()?[Book(path:path,title:p.getString('book.title')??'Untitled',page:p.getInt('book.page')??1,total:p.getInt('book.total')??0)]:[]; }
  static Future<void> save(Book b) async { final all=await loadAll(); final i=all.indexWhere((x)=>x.path==b.path); if(i>=0)all[i]=b; else all.add(b); final p=await SharedPreferences.getInstance(); await p.setString(key,jsonEncode(all.map((x)=>x.toJson()).toList())); try { await const MethodChannel('com.readflow/widget').invokeMethod('refresh'); } catch (_) {} }
  static Future<void> selectWidgetBook(Book b, {String? imagePath, String mode='text', String text='', List<String> chunks=const []}) async { final p=await SharedPreferences.getInstance(); await p.setString('widget.bookId',b.path); await p.setString('widget.title',b.title); await p.setInt('widget.page',b.page); if(imagePath!=null) await p.setString('widget.imagePath',imagePath); try { await const MethodChannel('com.readflow/widget').invokeMethod('refresh', {'bookId':b.path,'title':b.title,'page':b.page,'total':b.total,'imagePath':imagePath,'mode':mode,'text':text,'chunks':chunks}); } catch (_) {} }
  static Future<Set<int>> bookmarks(String path) async { final p=await SharedPreferences.getInstance(); return (p.getStringList('bookmarks.$path')??[]).map(int.parse).toSet(); }
  static Future<void> toggleBookmark(String path, int page) async { final p=await SharedPreferences.getInstance(); final key='bookmarks.$path'; final values=(p.getStringList(key)??[]).toSet(); values.contains('$page')?values.remove('$page'):values.add('$page'); await p.setStringList(key, values.toList()); }
}

class ReadflowApp extends StatelessWidget { const ReadflowApp({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false, theme:ThemeData(useMaterial3:true, colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff315c4c), brightness:Brightness.light), scaffoldBackgroundColor:const Color(0xfff8f6f0), fontFamily:'serif'), home:const LibraryScreen()); }

class LibraryScreen extends StatefulWidget { const LibraryScreen({super.key}); @override State<LibraryScreen> createState()=>_LibraryState(); }
class _LibraryState extends State<LibraryScreen> { List<Book> books=[]; bool loading=true; @override void initState(){super.initState(); Store.loadAll().then((b) async { if(!mounted)return; setState(() { books=b; loading=false; }); final pending=await const MethodChannel('com.readflow/widget').invokeMethod<dynamic>('pending'); if(pending is Map){final matches=b.where((x)=>x.path==pending['bookId']);if(matches.isNotEmpty && mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>ReaderScreen(book:matches.first,initialPage:(pending['page'] as num?)?.toInt())));} });}
  Future<void> importBook() async { final r=await FilePicker.pickFiles(type:FileType.custom,allowedExtensions:['pdf']); if(r?.files.single.path==null)return; final f=File(r!.files.single.path!); final dir=await getApplicationDocumentsDirectory(); final dest=File('${dir.path}/${DateTime.now().millisecondsSinceEpoch}_${f.uri.pathSegments.last}'); await f.copy(dest.path); final b=Book(path:dest.path,title:f.uri.pathSegments.last.replaceAll(RegExp(r'\.pdf$',caseSensitive:false),'')); await Store.save(b); if(mounted)setState(()=>books=[...books,b]); }
  void open(Book b){Navigator.push(context,MaterialPageRoute(builder:(_)=>ReaderScreen(book:b))).then((_){Store.loadAll().then((b){if(mounted)setState(()=>books=b);});});}
  Future<void> widgetSettings() async { await const MethodChannel('com.readflow/widget').invokeMethod('refresh'); if (!mounted) return; showModalBottomSheet(context: context, builder: (_) => const Padding(padding: EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.widgets_rounded, size: 42, color: Color(0xff315c4c)), SizedBox(height: 12), Text('Widget refreshed', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)), SizedBox(height: 8), Text('Remove and re-add the Readflow widget from your launcher if it still shows an old layout.', textAlign: TextAlign.center), SizedBox(height: 12)]))); }
  @override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator())); return Scaffold(appBar:AppBar(title:const Text('READFLOW',style:TextStyle(fontWeight:FontWeight.w800,letterSpacing:2)),backgroundColor:Colors.transparent,actions:[IconButton(onPressed:widgetSettings,tooltip:'Widget settings',icon:const Icon(Icons.widgets_outlined))]),body:Padding(padding:const EdgeInsets.fromLTRB(22,18,22,28),child:books.isEmpty?_Empty(onImport:importBook):Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('My Books',style:TextStyle(fontSize:28,fontWeight:FontWeight.w700)),const SizedBox(height:22),Expanded(child:ListView.separated(itemCount:books.length,itemBuilder:(_,i)=>_BookCard(book:books[i],onTap:()=>open(books[i])),separatorBuilder:(_,__)=>const SizedBox(height:12))),FilledButton.icon(onPressed:importBook,icon:const Icon(Icons.add),label:const Text('Add Book'))]))); }
}
class _Empty extends StatelessWidget { final VoidCallback onImport; const _Empty({required this.onImport}); @override Widget build(BuildContext c)=>Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.menu_book_rounded,size:72,color:Color(0xff315c4c)),const SizedBox(height:18),const Text('Your reading shelf is waiting.',style:TextStyle(fontSize:22,fontWeight:FontWeight.w700)),const SizedBox(height:8),const Text('Import a PDF to start reading locally.'),const SizedBox(height:24),FilledButton.icon(onPressed:onImport,icon:const Icon(Icons.add),label:const Text('Import Book'))])); }
class _BookCard extends StatelessWidget { final Book book; final VoidCallback onTap; const _BookCard({required this.book,required this.onTap}); @override Widget build(BuildContext c)=>Card(color:const Color(0xff315c4c),clipBehavior:Clip.antiAlias,child:InkWell(onTap:onTap,child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.auto_stories,color:Color(0xffe8d8aa),size:34),const SizedBox(height:30),Text(book.title,style:const TextStyle(color:Colors.white,fontSize:25,fontWeight:FontWeight.w800)),const SizedBox(height:14),Text(book.total>0?'${(book.progress*100).round()}% complete':'Ready to read',style:const TextStyle(color:Color(0xffd4e1d8))),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(book.total>0?'Page ${book.page} of ${book.total}':'Open your book',style:const TextStyle(color:Colors.white70)),const Icon(Icons.arrow_forward,color:Color(0xffe8d8aa))])])))); }
class ReaderScreen extends StatefulWidget { final Book book; final int? initialPage; const ReaderScreen({super.key,required this.book,this.initialPage}); @override State<ReaderScreen> createState()=>_ReaderState(); }
class _ReaderState extends State<ReaderScreen> { late int page; int total=0; double brightness=0, scale=1; PdfDocument? document; final tts=FlutterTts(); @override void initState(){super.initState();page=widget.initialPage??widget.book.page; PdfDocument.openFile(widget.book.path).then((d){if(mounted)setState((){document=d;total=d.pages.length;});cachePages();});}
  String normalizeWidgetText(String input) { return input.replaceAll(RegExp(r'-\s*\n'), '').replaceAll(RegExp(r'\s*\n\s*\n+'), '\n\n').replaceAll(RegExp(r'[ \t]+'), ' ').trim(); }
  Future<void> cachePages() async { if(document==null)return; final dir=await getApplicationDocumentsDirectory(); for(final n in [page-1,page,page+1]) { if(n<1||n>total)continue; final image=await document!.pages[n-1].render(fullWidth:420); if(image==null)continue; final rgba=Uint8List(image.pixels.length); for(var i=0;i<image.pixels.length;i+=4){rgba[i]=image.pixels[i+2];rgba[i+1]=image.pixels[i+1];rgba[i+2]=image.pixels[i];rgba[i+3]=image.pixels[i+3];} final png=img.encodePng(img.Image.fromBytes(width:image.width,height:image.height,bytes:rgba.buffer,order:img.ChannelOrder.rgba)); await File('${dir.path}/widget_page_$n.png').writeAsBytes(png); image.dispose();} }
  List<String> chunkText(String text) { // Never discard the delimiter or the character after it.
    if(text.isEmpty)return []; final out=<String>[]; var start=0;
    while(start<text.length){ var end=(start+650).clamp(start,text.length); if(end<text.length){ var boundary=-1;
      for(var i=end-1;i>=start+220;i--){ final ch=text[i]; if(ch=='.'||ch=='!'||ch=='?'||ch=='\n'||ch==' '){boundary=i;break;} }
      if(boundary>=start){ end=boundary+1; }
    }
    final part=text.substring(start,end).trim(); if(part.isNotEmpty)out.add(part); start=end;
    while(start<text.length && text[start].trim().isEmpty)start++;
    }
    return out;
  }
  Future<void> displayCurrentPageOnWidget() async { final raw=(await document?.pages[page-1].loadStructuredText())?.fullText??''; final text=normalizeWidgetText(raw); final chunks=chunkText(text); await cachePages(); final dir=await getApplicationDocumentsDirectory(); await Store.selectWidgetBook(Book(path:widget.book.path,title:widget.book.title,page:page,total:total),imagePath:'${dir.path}/widget_page_$page.png',mode:chunks.isEmpty?'original':'text',text:chunks.isEmpty?'Text unavailable — showing original page.':chunks.first,chunks:chunks); if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(chunks.isEmpty?'Text unavailable; original page selected.':'Reading text added to the widget'))); }
  Future<void> save(int p) async { page=p; await Store.save(Book(path:widget.book.path,title:widget.book.title,page:p,total:total));}
  Future<void> speak() async { if(document==null)return; final text=(await document!.pages[page-1].loadStructuredText()).fullText; await tts.stop(); await tts.speak(text.isEmpty?'No selectable text on this page.':text); }
  Future<void> searchInBook() async { if(document==null)return; final q=TextEditingController(); showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('Search book'),content:TextField(controller:q,autofocus:true,decoration:const InputDecoration(hintText:'Search text')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:() async { final needle=q.text.trim().toLowerCase(); if(needle.isEmpty)return; for(var i=1;i<=total;i++){ final t=(await document!.pages[i-1].loadStructuredText()).fullText.toLowerCase(); if(t.contains(needle)){if(ctx.mounted)Navigator.pop(ctx);await turn(i);return;} } if(ctx.mounted){Navigator.pop(ctx);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No match found')));}},child:const Text('Find'))])); }
  Future<void> turn(int next) async { if(total==0)return; final p=next.clamp(1,total); if(p!=page){setState(()=>page=p);await save(p);await cachePages();} }
  void showReadingControls() { showModalBottomSheet(context: context, builder: (_) => StatefulBuilder(builder: (c, setSheet) => Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [const Text('Reading controls', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)), Row(children: [const Icon(Icons.brightness_6), Expanded(child: Slider(value: brightness, min: 0, max: .7, onChanged: (v) { setSheet(() => brightness = v); setState(() => brightness = v); }))]), Row(children: [const Icon(Icons.text_fields), Expanded(child: Slider(value: scale, min: .85, max: 1.35, onChanged: (v) { setSheet(() => scale = v); setState(() => scale = v); }))]), const Text('Page scale zooms the fixed-layout PDF.')] )))); }
  @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.book.title),actions:[IconButton(onPressed:searchInBook,tooltip:'Search',icon:const Icon(Icons.search)),IconButton(onPressed:() async {await Store.toggleBookmark(widget.book.path,page);if(mounted)setState((){});},tooltip:'Bookmark page',icon:const Icon(Icons.bookmark_border)),PopupMenuButton<String>(onSelected:(v){if(v=='widget')displayCurrentPageOnWidget();if(v=='controls')showReadingControls();},itemBuilder:(_)=>const [PopupMenuItem(value:'widget',child:Text('Display this page on widget')),PopupMenuItem(value:'controls',child:Text('Reading controls'))]),IconButton(onPressed:speak,icon:const Icon(Icons.volume_up)),if(total>0)Center(child:Padding(padding:const EdgeInsets.only(right:16),child:Text('$page / $total')))]),body:document==null?const Center(child:CircularProgressIndicator()):Stack(children:[Column(children:[Expanded(child:GestureDetector(onHorizontalDragEnd:(d){if((d.primaryVelocity??0)<0)turn(page+1);else if((d.primaryVelocity??0)>0)turn(page-1);},child:AnimatedSwitcher(duration:const Duration(milliseconds:360),transitionBuilder:(child,animation)=>SlideTransition(position:Tween(begin:const Offset(1,0),end:Offset.zero).animate(CurvedAnimation(parent:animation,curve:Curves.easeOutCubic)),child:FadeTransition(opacity:animation,child:Transform.scale(scale:scale,child:child))),child:PdfPageView(key:ValueKey(page),document:document,pageNumber:page,backgroundColor:const Color(0xffddd9cf),decoration:const BoxDecoration(color:Colors.white,boxShadow:[BoxShadow(color:Colors.black26,blurRadius:8,offset:Offset(0,2))]))))),Padding(padding:const EdgeInsets.fromLTRB(20,8,20,18),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[IconButton(onPressed:page>1?()=>turn(page-1):null,icon:const Icon(Icons.chevron_left,size:32)),Text('Swipe or use the arrows',style:Theme.of(c).textTheme.bodySmall),IconButton(onPressed:page<total?()=>turn(page+1):null,icon:const Icon(Icons.chevron_right,size:32))]))]),if(brightness>0)Positioned.fill(child:IgnorePointer(child:ColoredBox(color:Colors.black.withOpacity(brightness))))])); }
